(* [comment removed for export] *)
Definition fl_b0_ok (b0 c0 : Z) : Prop := b0 mod 16 = 0 /\ 0 < c0.

Section FrameLawS.
Variable FSG : Type.
Variables MAPS0 RESV0 : list (word * word).
Variables (rn : art_run) (G : art_gs FSG) (LB : list (Z * Z)) (M M' : word -> option byte).
Hypothesis REP : art_alloc_rep FSG rn G LB M.
Hypothesis GRW : mem_grows M M'.
Variables (b0 c0 : Z).                                                     (* [comment removed for export] *)
Hypothesis AG : forall x : word, art_alloc_zone FSG rn G (U x) -> ~ in_block LB (U x) -> ~ in_shadow_of b0 c0 (U x) -> M' x = M x.
Hypothesis LSAN : cellA M' (rn_tp rn + rn_loff rn) 4 0.
Hypothesis LIVEOK : live_ok MAPS0 RESV0 (rn_HI rn) (art_live (g_log FSG G)).
Hypothesis KN : art_kn_ok MAPS0 RESV0 rn.
Hypothesis HB0 : In (b0, c0) LB.
Hypothesis HB0OK : fl_b0_ok b0 c0.
Hypothesis SHB0 : HAJ.shadow_blkR M' b0 c0.

